def comps(m):
    H,W=m.shape; seen=np.zeros_like(m,bool); out=[]
    for r in range(H):
        for c in range(W):
            if seen[r,c]: continue
            st=[(r,c)]; seen[r,c]=True; cl=[]
            while st:
                x,y=st.pop(); cl.append((x,y))
                for dy,dx in [(1,0),(-1,0),(0,1),(0,-1)]:
                    nr,nc=x+dy,y+dx
                    if 0<=nr<H and 0<=nc<W and not seen[nr,nc] and m[nr,nc]==m[x,y]:
                        seen[nr,nc]=True; st.append((nr,nc))
            out.append(cl)
    return out
